        has a duplicate name.
        """

        def _is_ignored(root: str, name: str) -> bool:
            path = os.path.normpath(os.path.join(root, name))
            return (
                name in self.config.ignore
                or any(pattern.match(name) for pattern in self.config.ignore_patterns)
                or any(
                    pattern.search(path) or pattern.search(path.replace(os.sep, "/"))
                    for pattern in self.config.ignore_paths
                )
            )

        for file_or_module in files_or_modules:
            if os.path.isdir(file_or_module):
                for root, directories, files in os.walk(file_or_module):
                    directories[:] = [
                        directory
                        for directory in directories
                        if not _is_ignored(root, directory)
                    ]
                    for file in files:
