class EvaluateFalseTransformer(ast.NodeTransformer):
    def visit_Compare(self, node):
        relations = {
            ast.Eq: 'Eq',
            ast.NotEq: 'Ne',
            ast.Lt: 'Lt',
            ast.LtE: 'Le',
            ast.Gt: 'Gt',
            ast.GtE: 'Ge',
        }
        operands = [self.visit(node.left)]
        operands.extend(self.visit(operand) for operand in node.comparators)

        comparisons = []
        for op, left, right in zip(node.ops, operands, operands[1:]):
            relation = relations.get(type(op))
            if relation is None:
                return self.generic_visit(node)
            comparisons.append(ast.Call(
                func=ast.Name(id=relation, ctx=ast.Load()),
                args=[left, right],
                keywords=[ast.keyword(
                    arg='evaluate', value=ast.Constant(value=False))],
            ))

        if len(comparisons) == 1:
            return comparisons[0]
        return ast.Call(
            func=ast.Name(id='And', ctx=ast.Load()),
            args=comparisons,
            keywords=[ast.keyword(
                arg='evaluate', value=ast.Constant(value=False))],
        )
